from fractions import Fraction

def expected_max(m, n):
    dp = [Fraction(0)] * (n + 1)
    dp[0] = Fraction(1)

    for i in range(1, n + 1):
        for j in range(i, 0, -1):
            dp[j] += dp[j - 1] * Fraction(j, m)

    return float(dp[n])

if __name__ == "__main__":
    input = sys.stdin.read
    data = input().split()
    m = int(data[0])
    n = int(data[1])
    result = expected_max(m, n)
    print(result)

